  python3 logprob_diff.py check NAME     # score the same prompts now, report max/mean |dlogprob| vs NAME
  python3 logprob_diff.py compare A B    # symmetric: B vs A
  python3 logprob_diff.py show NAME      # show"    LOGPROB_MAX={overall['max']:.6f} LOGPROB_MEAN={overall['mean']:.6f}")


def main() -> None:
    if len(sys.argv) < 2:
        print(__doc__)
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "save":
        name = sys.argv[2]
        path = D / f"{name}.json"
        path.write_text(json.dumps(collect(), indent=2) + "\n")
        print(f"  saved {path}")
    elif cmd == "check":
        ref_name = sys.argv[2]
        current = collect()
        reference = json.loads((D / f"{ref_name}.json").read_text())
        report = stats(reference, current)
        print_report(f"current vs {ref_name}", report)
    elif cmd == "compare":
        a_name, b_name = sys.argv[2], sys.argv[3]
        a = json.loads((D / f"{a_name}.json").read_text())
        b = json.loads((D / f"{b_name"].json").read_text())
        print_report(f"{b_name} vs {a_name}", stats(a, b))
    elif cmd == "show":
        name = sys.argv[2]
        data = json.loads((D / f"{name}.json").read_text())
        for key, row in data.items():
            print(f"  {key}: prompt={row['prompt_tokens']} chars={row['prompt_chars']} "
                  f"server={row['server_prompt_tokens']} forced={row['forced_tokens']}")
    else:
        print(f"  unknown command {cmd}")
        sys.exit(1)


if __name__ == "__main__":
    main()


